// Some portions generated by Claude
package org.eclipse.rdf4j.sail.memory;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.TreeMap;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/**
 * SPARQL's {@code substitute()} for EXISTS replaces the variables of the outer row inside the EXISTS body, but a
 * sub-select inside that body only exposes its projected variables: every variable it does not project is fresh inside
 * it and must neither be substituted nor pre-bound, while a projected variable is substituted before the sub-select's
 * LIMIT or aggregation is applied. Every expected bag below is hand-computed from those semantics.
 */
class ExistsSubSelectScopeTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String PREFIX = "PREFIX : <urn:ex:>\n";

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	private static IRI iri(String local) {
		return VF.createIRI("urn:ex:" + local);
	}

	@ParameterizedTest(name = "negated={0}")
	@ValueSource(booleans = { false, true })
	void existsOverSubSelectDoesNotSubstituteNonProjectedVariable(boolean negated) {
		add(iri("a"), iri("p"), VF.createLiteral(1));
		add(iri("c"), iri("r"), VF.createLiteral(2));
		// ?x is not projected: inside the sub-select it is fresh, so ?t :r ?x matches :c and EXISTS is true
		String query = PREFIX + """
				SELECT ?s WHERE {
				  ?s :p ?x
				  FILTER %s { { SELECT ?t WHERE { ?t :r ?x } } }
				}
				""".formatted(negated ? "NOT EXISTS" : "EXISTS");
		if (negated) {
			assertThat(rows(query)).isEmpty();
		} else {
			assertThat(rows(query)).containsExactly("{s=urn:ex:a}");
		}
	}

	@ParameterizedTest(name = "negated={0}")
	@ValueSource(booleans = { false, true })
	void existsOverAggregateSubSelectDoesNotSubstituteNonProjectedVariable(boolean negated) {
		add(iri("a"), iri("p"), iri("o1"));
		add(iri("t1"), iri("r"), iri("o1"));
		add(iri("t2"), iri("r"), iri("o2"));
		// COUNT over all :r triples is 2, so HAVING(?n > 1) holds independently of the outer ?o
		String query = PREFIX + """
				SELECT ?s WHERE {
				  ?s :p ?o
				  FILTER %s { SELECT (COUNT(?o) AS ?n) WHERE { ?t :r ?o } HAVING (COUNT(?o) > 1) }
				}
				""".formatted(negated ? "NOT EXISTS" : "EXISTS");
		if (negated) {
			assertThat(rows(query)).isEmpty();
		} else {
			assertThat(rows(query)).containsExactly("{s=urn:ex:a}");
		}
	}

	@ParameterizedTest(name = "negated={0}")
	@ValueSource(booleans = { false, true })
	void existsOverSubSelectJoinedWithPatternDoesNotSubstituteNonProjectedVariable(boolean negated) {
		add(iri("a"), iri("p"), VF.createLiteral(1));
		add(iri("c"), iri("r"), VF.createLiteral(2));
		add(iri("c"), iri("z"), iri("y1"));
		// the sub-select is the left operand of a join inside the EXISTS body; ?x is still fresh inside it
		String query = PREFIX + """
				SELECT ?s WHERE {
				  ?s :p ?x
				  FILTER %s { { SELECT ?t WHERE { ?t :r ?x } } ?t :z ?y }
				}
				""".formatted(negated ? "NOT EXISTS" : "EXISTS");
		if (negated) {
			assertThat(rows(query)).isEmpty();
		} else {
			assertThat(rows(query)).containsExactly("{s=urn:ex:a}");
		}
	}

	@ParameterizedTest(name = "negated={0}")
	@ValueSource(booleans = { false, true })
	void existsOverLimitedSubSelectSubstitutesProjectedVariableBeforeTheLimit(boolean negated) {
		add(iri("a"), iri("p"), VF.createLiteral(2));
		add(iri("c"), iri("r"), VF.createLiteral(1));
		add(iri("d"), iri("r"), VF.createLiteral(2));
		// ?x is projected, so substitute() replaces it inside the sub-select: ?t :r 2 has a row, LIMIT 1 keeps it and
		// EXISTS is true. (Evaluating the sub-select unbound would pick {t=:c, x=1} and wrongly report false.)
		String query = PREFIX + """
				SELECT ?s WHERE {
				  ?s :p ?x
				  FILTER %s { SELECT ?x WHERE { ?t :r ?x } ORDER BY ?x LIMIT 1 }
				}
				""".formatted(negated ? "NOT EXISTS" : "EXISTS");
		if (negated) {
			assertThat(rows(query)).isEmpty();
		} else {
			assertThat(rows(query)).containsExactly("{s=urn:ex:a}");
		}
	}

	@Test
	void existsOverGroupedSubSelectSubstitutesProjectedGroupKey() {
		add(iri("a"), iri("p"), iri("o1"));
		add(iri("b"), iri("p"), iri("o2"));
		add(iri("t1"), iri("r"), iri("o1"));
		add(iri("t2"), iri("r"), iri("o1"));
		add(iri("t3"), iri("r"), iri("o2"));
		// ?o is projected: the group for the outer ?o is the one HAVING inspects (2 rows for o1, 1 row for o2)
		String query = PREFIX + """
				SELECT ?s WHERE {
				  ?s :p ?o
				  FILTER EXISTS { SELECT ?o WHERE { ?t :r ?o } GROUP BY ?o HAVING (COUNT(?t) > 1) }
				}
				""";
		assertThat(rows(query)).containsExactly("{s=urn:ex:a}");
	}

	@Test
	void notExistsOverSubSelectRemovesRowsWhoseProjectedValueMatches() {
		add(iri("a"), iri("p"), VF.createLiteral(1));
		add(iri("b"), iri("p"), VF.createLiteral(2));
		add(iri("c"), iri("r"), VF.createLiteral(2));
		String query = PREFIX + """
				SELECT ?s WHERE {
				  ?s :p ?x
				  FILTER NOT EXISTS { SELECT ?x WHERE { ?t :r ?x } }
				}
				""";
		assertThat(rows(query)).containsExactly("{s=urn:ex:a}");
	}

	@Test
	void existsInsideJoinedGroupDoesNotSeeOuterJoinBinding() {
		List<String> expected = new ArrayList<>();
		for (int i = 0; i < 40; i++) {
			add(iri("s" + i), iri("q"), iri("o" + i));
			add(iri("s" + i), iri("r"), iri("w" + i));
			expected.add("{a=urn:ex:a, s=urn:ex:s" + i + "}");
		}
		add(iri("a"), iri("p"), iri("zzz"));
		expected.sort(Comparator.naturalOrder());
		// inside the group ?z is not in scope, so EXISTS { ?s :r ?z } only needs some :r edge from ?s
		String query = PREFIX + """
				SELECT ?a ?s WHERE {
				  ?a :p ?z .
				  { ?s :q ?o FILTER EXISTS { ?s :r ?z } }
				}
				""";
		assertThat(rows(query)).containsExactlyElementsOf(expected);
	}

	@ParameterizedTest(name = "negated={0}")
	@ValueSource(booleans = { false, true })
	void existsUnionBodyAfterMaterializationBudget(boolean negated) {
		List<String> expected = new ArrayList<>();
		for (int i = 0; i < 80; i++) {
			add(iri("s" + i), iri("p"), iri("x" + i));
			if (i % 2 == 0) {
				add(iri("s" + i), iri("q"), iri("y" + i));
			}
			if (i % 3 == 0) {
				add(iri("x" + i), iri("r"), iri("w"));
			}
			boolean exists = i % 2 == 0 || i % 3 == 0;
			if (exists != negated) {
				expected.add("{s=urn:ex:s" + i + "}");
			}
		}
		expected.sort(Comparator.naturalOrder());
		String query = PREFIX + """
				SELECT ?s WHERE {
				  ?s :p ?x
				  FILTER %s { { ?s :q ?y } UNION { ?x :r ?w } }
				}
				""".formatted(negated ? "NOT EXISTS" : "EXISTS");
		assertThat(rows(query)).containsExactlyElementsOf(expected);
	}

	private void add(IRI subject, IRI predicate, Value object) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, object);
		}
	}

	private List<String> rows(String query) {
		List<String> rows = new ArrayList<>();
		try (SailRepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			while (result.hasNext()) {
				BindingSet bindingSet = result.next();
				TreeMap<String, String> sorted = new TreeMap<>();
				for (String name : bindingSet.getBindingNames()) {
					Value value = bindingSet.getValue(name);
					if (value != null) {
						sorted.put(name, value.stringValue());
					}
				}
				rows.add(sorted.toString());
			}
		}
		rows.sort(Comparator.naturalOrder());
		return rows;
	}
}
